  SELECT 19 AS ord, 'account-deletion guard triggers: 13' AS "check", ((SELECT count(DISTINCT c.relname) FROM pg_trigger g JOIN pg_class c ON c.oid = g.tgrelid JOIN pg_namespace n ON n.oid = c.relnamespace WHERE g.tgname = 'backlot_account_guard' AND n.nspname = 'public' AND g.tgenabled = 'O') = 13) AS ok, ((SELECT count(*) FROM pg_trigger WHERE tgname = 'backlot_account_guard')::text || ' found')::text AS detail
UNION ALL
  SELECT 20 AS ord, 'row-level security off on Backlot tables (backlot_app has no policies and no bypass)' AS "check", ((SELECT count(*) FROM unnest(ARRAY['account_deletions', 'channels', 'content_items', 'ideas', 'slate_action_events', 'slate_actions', 'slate_breaker_state', 'slate_conversations', 'slate_embeddings', 'slate_messages', 'slate_preferences', 'slate_usage_leases', 'upload_sessions', 'uploaded_files', 'users']::text[]) AS t WHERE NOT (NOT coalesce((SELECT relrowsecurity FROM pg_class WHERE oid = to_regclass('public.' || t)), true))) = 0) AS ok, ('RLS on: ' || coalesce((SELECT string_agg(t, ', ' ORDER BY t) FROM unnest(ARRAY['account_deletions', 'channels', 'content_items', 'ideas', 'slate_action_events', 'slate_actions', 'slate_breaker_state', 'slate_conversations', 'slate_embeddings', 'slate_messages', 'slate_preferences', 'slate_usage_leases', 'upload_sessions', 'uploaded_files', 'users']::text[]) AS t WHERE NOT (NOT coalesce((SELECT relrowsecurity FROM pg_class WHERE oid = to_regclass('public.' || t)), true))), ''))::text AS detail
UNION ALL
  SELECT 21 AS ord, 'legacy objects kept in legacy_init' AS "check", ((SELECT count(*) FROM information_schema.tables WHERE table_schema = 'legacy_init') = 3 AND to_regprocedure('legacy_init.set_updated_at()') IS NOT NULL) AS ok, ((SELECT string_agg(table_name, ', ' ORDER BY table_name) FROM information_schema.tables WHERE table_schema = 'legacy_init'))::text AS detail
UNION ALL
  SELECT 22 AS ord, 'legacy_init not usable by anon / authenticated' AS "check", (NOT has_schema_privilege('anon', 'legacy_init', 'USAGE') AND NOT has_schema_privilege('authenticated', 'legacy_init', 'USAGE')) AS ok, ('')::text AS detail
UNION ALL
  SELECT 23 AS ord, 'anon / authenticated have no access to any public table' AS "check", ((SELECT count(*) FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 'public' AND c.relkind IN ('r', 'p') AND (has_table_privilege('anon', c.oid, 'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER') OR has_table_privilege('authenticated', c.oid, 'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER'))) = 0) AS ok, ((SELECT string_agg(c.relname, ', ' ORDER BY c.relname) FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 'public' AND c.relkind IN ('r', 'p') AND (has_table_privilege('anon', c.oid, 'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER') OR has_table_privilege('authenticated', c.oid, 'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER'))))::text AS detail
UNION ALL
  SELECT 24 AS ord, 'backlot_app: login, no superuser / createrole / createdb / replication / bypassrls, noinherit' AS "check", (EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'backlot_app' AND rolcanlogin AND NOT rolsuper AND NOT rolcreaterole AND NOT rolcreatedb AND NOT rolreplication AND NOT rolbypassrls AND NOT rolinherit)) AS ok, ('')::text AS detail
UNION ALL
  SELECT 25 AS ord, 'backlot_app owns nothing and is a member of no role' AS "check", (NOT EXISTS (SELECT 1 FROM pg_class c JOIN pg_roles r ON r.oid = c.relowner WHERE r.rolname = 'backlot_app') AND NOT EXISTS (SELECT 1 FROM pg_namespace s JOIN pg_roles r ON r.oid = s.nspowner WHERE r.rolname = 'backlot_app') AND NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_roles r ON r.oid = p.proowner WHERE r.rolname = 'backlot_app') AND NOT EXISTS (SELECT 1 FROM pg_auth_members m JOIN pg_roles r ON r.oid = m.member WHERE r.rolname = 'backlot_app')) AS ok, ('')::text AS detail
UNION ALL
  SELECT 26 AS ord, 'backlot_app: SELECT/INSERT/UPDATE/DELETE on every Backlot table' AS "check", ((SELECT count(*) FROM unnest(ARRAY['account_deletions', 'channels', 'content_items', 'ideas', 'slate_action_events', 'slate_actions', 'slate_breaker_state', 'slate_conversations', 'slate_embeddings', 'slate_messages', 'slate_preferences', 'slate_usage_leases', 'upload_sessions', 'uploaded_files', 'users']::text[]) AS t WHERE NOT (coalesce(has_table_privilege('backlot_app', to_regclass('public.' || t), 'SELECT'), false) AND coalesce(has_table_privilege('backlot_app', to_regclass('public.' || t), 'INSERT'), false) AND coalesce(has_table_privilege('backlot_app', to_regclass('public.' || t), 'UPDATE'), false) AND coalesce(has_table_privilege('backlot_app', to_regclass('public.' || t), 'DELETE'), false))) = 0) AS ok, ('missing on: ' || coalesce((SELECT string_agg(t, ', ' ORDER BY t) FROM unnest(ARRAY['account_deletions', 'channels', 'content_items', 'ideas', 'slate_action_events', 'slate_actions', 'slate_breaker_state', 'slate_conversations', 'slate_embeddings', 'slate_messages', 'slate_preferences', 'slate_usage_leases', 'upload_sessions', 'uploaded_files', 'users']::text[]) AS t WHERE NOT (coalesce(has_table_privilege('backlot_app', to_regclass('public.' || t), 'SELECT'), false) AND coalesce(has_table_privilege('backlot_app', to_regclass('public.' || t), 'INSERT'), false) AND coalesce(has_table_privilege('backlot_app', to_regclass('public.' || t), 'UPDATE'), false) AND coalesce(has_table_privilege('backlot_app', to_regclass('public.' || t), 'DELETE'), false))), ''))::text AS detail
UNION ALL
  SELECT 27 AS ord, 'backlot_app: no TRUNCATE / REFERENCES / TRIGGER' AS "check", ((SELECT count(*) FROM unnest(ARRAY['account_deletions', 'channels', 'content_items', 'ideas', 'slate_action_events', 'slate_actions', 'slate_breaker_state', 'slate_conversations', 'slate_embeddings', 'slate_messages', 'slate_preferences', 'slate_usage_leases', 'upload_sessions', 'uploaded_files', 'users']::text[]) AS t WHERE NOT (coalesce(NOT has_table_privilege('backlot_app', to_regclass('public.' || t), 'TRUNCATE,REFERENCES,TRIGGER'), false))) = 0) AS ok, ('')::text AS detail
UNION ALL
  SELECT 28 AS ord, 'backlot_app: no access to backlot_schema_migrations' AS "check", (coalesce(NOT has_table_privilege('backlot_app', to_regclass('public.backlot_schema_migrations'), 'SELECT,INSERT,UPDATE,DELETE,TRUNCATE'), false)) AS ok, ('')::text AS detail
UNION ALL
  SELECT 29 AS ord, 'backlot_app: USAGE and UPDATE on every public sequence' AS "check", ((SELECT count(*) FROM pg_class s JOIN pg_namespace n ON n.oid = s.relnamespace WHERE s.relkind = 'S' AND n.nspname = 'public' AND NOT (has_sequence_privilege('backlot_app', s.oid, 'USAGE') AND has_sequence_privilege('backlot_app', s.oid, 'UPDATE'))) = 0) AS ok, ('')::text AS detail
UNION ALL
  SELECT 30 AS ord, 'backlot_backup: login, no write roles' AS "check", (EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'backlot_backup' AND rolcanlogin AND NOT rolsuper AND NOT rolcreaterole AND NOT rolcreatedb AND NOT rolbypassrls)) AS ok, ('')::text AS detail
