  SELECT 31 AS ord, 'backlot_backup: SELECT on every Backlot table' AS "check", ((SELECT count(*) FROM unnest(ARRAY['account_deletions', 'channels', 'content_items', 'ideas', 'slate_action_events', 'slate_actions', 'slate_breaker_state', 'slate_conversations', 'slate_embeddings', 'slate_messages', 'slate_preferences', 'slate_usage_leases', 'upload_sessions', 'uploaded_files', 'users']::text[]) AS t WHERE NOT (coalesce(has_table_privilege('backlot_backup', to_regclass('public.' || t), 'SELECT'), false))) = 0) AS ok, ('missing on: ' || coalesce((SELECT string_agg(t, ', ' ORDER BY t) FROM unnest(ARRAY['account_deletions', 'channels', 'content_items', 'ideas', 'slate_action_events', 'slate_actions', 'slate_breaker_state', 'slate_conversations', 'slate_embeddings', 'slate_messages', 'slate_preferences', 'slate_usage_leases', 'upload_sessions', 'uploaded_files', 'users']::text[]) AS t WHERE NOT (coalesce(has_table_privilege('backlot_backup', to_regclass('public.' || t), 'SELECT'), false))), ''))::text AS detail
UNION ALL
  SELECT 32 AS ord, 'backlot_backup: cannot write' AS "check", ((SELECT count(*) FROM unnest(ARRAY['account_deletions', 'channels', 'content_items', 'ideas', 'slate_action_events', 'slate_actions', 'slate_breaker_state', 'slate_conversations', 'slate_embeddings', 'slate_messages', 'slate_preferences', 'slate_usage_leases', 'upload_sessions', 'uploaded_files', 'users']::text[]) AS t WHERE NOT (coalesce(NOT has_table_privilege('backlot_backup', to_regclass('public.' || t), 'INSERT,UPDATE,DELETE,TRUNCATE'), false))) = 0) AS ok, ('')::text AS detail
UNION ALL
  SELECT 33 AS ord, 'backlot_backup read access path (information)' AS "check", (true) AS ok, (CASE WHEN pg_has_role('backlot_backup', 'pg_read_all_data', 'MEMBER') THEN 'pg_read_all_data' ELSE 'per-table SELECT grants' END)::text AS detail
) AS checks ORDER BY ord;
